<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from "vue";import {useRoute} from "vue-router";import Navbar from "@/components/Navbar.vue";import BookGrid from "@/components/BookGrid.vue";import BookCollectionFilters from "@/components/BookCollectionFilters.vue";
const route=useRoute(),names={want_to_read:"Want to Read",reading:"Currently Reading",finished:"Finished",paused:"Paused",dnf:"Did Not Finish"},status=computed(()=>String(route.params.status??"")),title=computed(()=>names[status.value]??""),books=ref([]),loading=ref(true),error=ref(""),filters=ref({q:"",genres:[],categories:[],sort:"recently_updated_desc"});let controller=null;
async function fetchBooks(next=filters.value){if(!title.value){loading.value=false;return}filters.value=next;controller?.abort();controller=new AbortController();loading.value=true;try{const p=new URLSearchParams({status:status.value,q:next.q,sort:next.sort});if(next.categories?.length)p.set("categories",next.categories.join(","));else if(next.genres.length)p.set("genres",next.genres.join(","));const r=await fetch(`/api/books.php?${p}`,{signal:controller.signal}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Could not load this list.");books.value=Array.isArray(d)?d:[]}catch(e){if(e.name!=="AbortError")error.value=e.message}finally{if(!controller.signal.aborted)loading.value=false}}
const refreshBooks=()=>fetchBooks(filters.value);watch(status,()=>{filters.value={q:"",genres:[],categories:[],sort:"recently_updated_desc"};fetchBooks()});onMounted(()=>{fetchBooks();window.addEventListener("bookshelf:books-synced",refreshBooks)});onUnmounted(()=>{controller?.abort();window.removeEventListener("bookshelf:books-synced",refreshBooks)});
</script>
<template><Navbar/><main class="container py-4"><h1 v-if="title" class="mb-4">{{title}}</h1><p v-if="!title" class="alert alert-danger">This reading list does not exist.</p><template v-else><BookCollectionFilters :status="status" @change="fetchBooks"/><p v-if="loading">Loading books...</p><p v-else-if="error" class="alert alert-danger">{{error}}</p><BookGrid v-else :books="books" @status-change="refreshBooks"/></template></main></template>
